hl.on("hyprland.start", function()
    hl.exec_cmd("awww-daemon &")
    hl.exec_cmd("xrandr --output eDP-1 --primary")
    hl.exec_cmd("/usr/lib/polkit-gnome/polkit-gnome-authentication-agent-1")
    hl.exec_cmd("gsettings set org.gnome.desktop.interface color-scheme 'prefer-dark'")
    hl.exec_cmd("/home/a7med/.config/hypr/scripts/workspace-apps/layout1.sh")
    hl.exec_cmd("/home/a7med/.config/hypr/scripts/workspace-apps/layout2.sh")
    hl.exec_cmd("/home/a7med/.config/hypr/scripts/workspace-apps/layout3.sh")
    hl.exec_cmd("/home/a7med/.config/hypr/scripts/workspace-apps/layout4.sh")
    hl.exec_cmd("wl-paste --type text --watch cliphist store")
    hl.exec_cmd("wl-paste --type image --watch cliphist store")
    hl.exec_cmd("fcitx5")
    hl.exec_cmd("noctalia")
    hl.exec_cmd("wayscriber -d")
    hl.exec_cmd("killall openbox")
end)

